package com.hrcoresystem.hrcore_api.modules.tenant.employees.infrastructure.api;
import com.hrcoresystem.hrcore_api.common.response.ApiResponse; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.usecase.ListMyTeamEmployeesUseCase; import com.hrcoresystem.hrcore_api.modules.tenant.departments.application.dto.OrganizationalEmployeeSummaryResponse; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/my-team") public class MyTeamController { private final ListMyTeamEmployeesUseCase useCase; public MyTeamController(ListMyTeamEmployeesUseCase u){useCase=u;} @GetMapping("/employees") @PreAuthorize("hasAuthority('employees.team.read')") public ApiResponse<Page<OrganizationalEmployeeSummaryResponse>> employees(@PageableDefault(size=25) Pageable pageable){return ApiResponse.success("Equipo consultado correctamente",useCase.execute(pageable));} }
